    struct Case {
        let width: Int
        let height: Int
        /// The `bitmap_fmt` in the payload's second byte.
        let format: UInt8
        let topDown: Bool
        /// The whole image payload: two header bytes and then the blocks.
        let payload: String
        /// What the blocks decode to — packed rows of `width × bytes-per-pixel`
        /// with no padding, before any conversion to BGRA.
        let rows: String
    }

    static func bytes(_ hex: String) -> [UInt8] {
        let digits = hex.filter { !$0.isWhitespace }
        var out: [UInt8] = []
        out.reserveCapacity(digits.count / 2)
        var index = digits.startIndex
        while index < digits.endIndex {
            let next = digits.index(index, offsetBy: 2)
            out.append(UInt8(digits[index..<next], radix: 16) ?? 0)
            index = next
        }
        return out
    }

